WITH flattened AS (SELECT id, plan, EXPLODE_OUTER(discounts) AS tier_value FROM price_tiers) SELECT id, plan, PERCENT_RANK() OVER (PARTITION BY plan ORDER BY tier_value DESC) AS tier_value_percent_rank, CUME_DIST() OVER (PARTITION BY plan ORDER BY tier_value DESC) AS tier_value_cume_dist, DENSE_RANK() OVER (PARTITION BY plan ORDER BY tier_value DESC) AS tier_value_dense_rank FROM flattened
